const fs = require('fs');
const path = require('path');

// Minimal valid MP3 (short silence) - from known minimal mp3 data URI
const minimalMp3Base64 =
  '';

const soundsDir = path.join(__dirname, '..', 'assets', 'sounds');
if (!fs.existsSync(soundsDir)) {
  fs.mkdirSync(soundsDir, { recursive: true });
}
const buf = Buffer.from(minimalMp3Base64, 'base64');
['azan1.mp3', 'azan2.mp3'].forEach((file) => {
  fs.writeFileSync(path.join(soundsDir, file), buf);
  console.log('Created', file);
});
